#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# The wizard reads the human's keyboard. A shell without one (an agent's tool
# call, a `!` prompt prefix, a pipe) would end at the first prompt in silence.
if [[ ! -t 0 ]]; then
  printf 'This wizard needs a keyboard: run it in your own terminal window.\n' >&2
  exit 1
fi

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# 티켓 26 2절: Fusion에서 첫 업로드를 하고 녹화본을 만든다(docs/recording-guide.md).
# 녹화본·요점·메모는 fixtures/private/recordings/(공개 저장소에 올라가지 않음)에 남는다.
cd "$(dirname "$0")/.."
SERVER=http://localhost:8000
REC_DIR=fixtures/private/recordings
mkdir -p "$REC_DIR" data/uploads
SERVER_PID=""

# Windows의 .venv/Scripts/uvicorn.exe는 python.exe를 자식으로 띄우는 실행기라, 실행기만 끄면 서버가 포트를 쥔 채
# 남는다. 프로세스 트리째 끈다.
stop_server() {
  [[ -n "$SERVER_PID" ]] || return 0
  if [[ -r "/proc/$SERVER_PID/winpid" ]]; then
    taskkill //T //F //PID "$(cat "/proc/$SERVER_PID/winpid")" >/dev/null 2>&1 || true
  else
    kill "$SERVER_PID" 2>/dev/null || true
  fi
  SERVER_PID=""
}
trap stop_server EXIT

wait_health() {
  until curl -sf -m 3 "$SERVER/health" >/dev/null; do
    if [[ -n "$SERVER_PID" ]] && ! kill -0 "$SERVER_PID" 2>/dev/null; then
      warn "서버가 뜨지 못했다. data/recording-server.log 를 본다."
      exit 1
    fi
    sleep 1
  done
}

# addin_error 기준파일 제목: 애드인이 기준파일보다 뒤에 남긴 그 제목의 실패 기록(scripts/last_error.py). 사람이 창의
# 문장을 옮겨 적지 않아도 되게 애드인이 data/addin-checks/last-error.txt에 쓴다(ConfiguratorUploader._report).
ADDIN_ERROR=data/addin-checks/last-error.txt
addin_error() {
  PYTHONUTF8=1 .venv/Scripts/python -m scripts.last_error "$ADDIN_ERROR" "$1" "$2" || true
}

run_wizard() {

TOTAL_STAGES=6

banner "티켓 26 2절: Fusion 첫 업로드와 녹화"

stage "모델 준비"
say "업로드할 모델을 Fusion에서 연다. stool1이나 슬라이더 1~2개짜리 단순한 실제 상품이면 된다."
step "파라메트릭 디자인이고, 슬라이더로 쓸 치수가 사용자 파라미터다. 기본값은 0이 아니다."
step "타임라인에 오류(빨간 표시)가 없다. 상품이 아닌 바디(보조·참고용)는 숨긴다."
step "모델을 먼저 저장한다. 업로드는 파라미터를 바꿨다가 되돌린다."
note "앞서 업로드가 실패했다면 그 모델은 저장하지 말고, 저장해 둔 판으로 다시 연다. 끊긴 업로드가 바꾼 값이 남아 있을 수 있다."
note "가능하면 컴포넌트로 나뉘고 둥근 부분(원형 구멍, 둥근 다리)이 있는 모델을 고른다. 이번 확인의 목적이다."
note "면은 평면과 원기둥만 다룬다. 모따기한 구멍(원뿔)이나 구·자유곡면이 있으면 업로드가 멈춘다."
while true; do
  ask REC_NAME "녹화본 이름(영문·숫자·_·-):"
  [[ "$REC_NAME" =~ ^[A-Za-z0-9_-]+$ ]] && break
  warn "영문·숫자·_·-만 쓴다."
done
[[ -f "$REC_DIR/$REC_NAME.json" ]] && warn "$REC_DIR/$REC_NAME.json 이 이미 있다. 녹화하면 덮어쓴다."
pause "모델을 열고 저장했으면 Enter"

stage "서버"
if [[ ! -x .venv/Scripts/python ]]; then
  say "Python 가상 환경(.venv)이 없다. 녹화 안내서 4-1처럼 처음 한 번 설치한다."
  if confirm "지금 설치할까?"; then
    python -m venv .venv
    .venv/Scripts/python -m pip install -e ".[dev]"
  else
    warn "설치한 뒤 다시 돌린다."
    exit 1
  fi
fi
if curl -sf -m 3 "$SERVER/health" >/dev/null; then
  if docker compose ps --status running --services 2>/dev/null | grep -qx server; then
    say "Docker 구성의 server가 떠 있다. 업로드는 data/uploads/, 녹화본은 $REC_DIR/ 에 남는다."
    note "컨테이너는 이미지를 만들 때의 서버 코드로 돈다. 그 뒤 서버 코드가 바뀌었으면 다시 만들어야 한다."
    if confirm "지금 코드로 server 이미지를 다시 만들까? (1~2분)"; then
      docker compose up -d --build server
      wait_health
    fi
  else
    say "$SERVER 에 서버가 이미 떠 있다. 그대로 쓴다."
    note "이 저장소 폴더에서 띄운 서버가 아니면 업로드를 찾지 못한다. 그때는 업로드 단계에서 ID를 직접 넣는다."
  fi
else
  say "서버를 띄운다. 이 위저드가 끝나면 함께 꺼진다."
  .venv/Scripts/uvicorn server.main:app --host 127.0.0.1 --port 8000 > data/recording-server.log 2>&1 &
  SERVER_PID=$!
  wait_health
fi
say "${GREEN}✓${RESET} 서버가 답한다."
pause "Enter"

stage "애드인 실행"
ADDIN_FOLDER=$(cygpath -w "$PWD/addin/ConfiguratorUploader" 2>/dev/null || echo "$PWD/addin/ConfiguratorUploader")
step "Fusion에서 Shift+S를 눌러 \"스크립트 및 추가 기능\" 창을 연다."
step "ConfiguratorUploader가 목록에 없으면 창 위의 + 로(예전 화면이면 \"추가 기능\" 탭의 + 로) 아래 폴더를 추가한다."
say ""
say "  ${BOLD}$ADDIN_FOLDER${RESET}"
if command -v clip.exe >/dev/null 2>&1; then
  printf '%s' "$ADDIN_FOLDER" | clip.exe && note "폴더 경로를 클립보드에 복사했다."
fi
say ""
step "이미 실행 중이면 \"중지\"한 뒤 다시 \"실행\"한다. 그래야 이번에 바뀐 애드인 코드를 읽는다."
step "디자인 작업공간 → 유틸리티 탭 → 추가 기능 패널에 \"구성기 업로드\" 버튼이 보이면 된다."
note "서버 주소는 addin/ConfiguratorUploader/config.py 의 SERVER_URL($(grep -o 'http[^"]*' addin/ConfiguratorUploader/config.py))이다."
pause "버튼이 보이면 Enter"

stage "업로드"
# 파일 시각 대신 목록 차이로 찾는다. Docker 쪽 시계가 Windows와 어긋나도 놓치지 않는다.
before=$(ls data/uploads)
MARK=$(mktemp)
DRY_RESULT="돌리지 않음"
if confirm "처음 올리는 모델이면 먼저 \"구성기 업로드 점검\"(서버에 올리지 않음)을 돌릴까?"; then
  dry_before=$(ls data/dry-runs 2>/dev/null || true)
  step "\"구성기 업로드 점검\"을 누르고 메시지 창이 뜰 때까지 기다린다. 업로드와 같은 시간이 걸린다."
  pause "창이 뜨면 Enter"
  # shellcheck disable=SC2012  # ls는 위저드가 만드는 폴더의 파일 이름(공백·줄바꿈 없음)만 다룬다
  dry=$(comm -13 <(printf '%s\n' "$dry_before" | sort) <(ls data/dry-runs 2>/dev/null | sort) | grep '\.json$' | tail -n1 || true)
  if [[ -n "$dry" ]]; then
    dry_summary=$(PYTHONUTF8=1 .venv/Scripts/python -m scripts.recording_summary "data/dry-runs/$dry" 2>&1) || true
    while IFS= read -r line; do note "$line"; done <<< "$dry_summary"
    if grep -qx "서버 묶음 검사: 통과" <<< "$dry_summary"; then
      DRY_RESULT="통과(data/dry-runs/$dry)"
      say "${GREEN}✓${RESET} 점검 묶음이 서버 묶음 검사를 통과했다. 애드인 점검은 data/addin-checks/${dry%.json}.json 에 있다."
    else
      DRY_RESULT="묶음 검사 실패(data/dry-runs/$dry)"
      warn "점검 묶음이 서버 묶음 검사를 통과하지 못했다. 진짜 업로드도 서버가 거절한다."
      confirm "그래도 진짜 업로드를 할까?" || { SKIPPED+=("업로드(점검 실패)"); finish; exit 0; }
    fi
  else
    DRY_ERROR=$(addin_error "$MARK" "업로드 점검 실패")
    if [[ -n "$DRY_ERROR" ]]; then
      warn "점검이 실패했다: $DRY_ERROR"
    else
      ask DRY_ERROR "점검 묶음도 애드인의 실패 기록도 없다. 메시지 창의 문장(첫 줄과 마지막 줄, 없으면 Enter):"
    fi
    DRY_RESULT="실패: ${DRY_ERROR:-문장 없음}"
    confirm "그래도 진짜 업로드를 할까?" || { SKIPPED+=("업로드(점검 실패)"); finish; exit 0; }
  fi
fi
# 점검 단계의 실패를 업로드 실패로 읽지 않게 기준을 새로 잡는다
touch "$MARK"
step "\"구성기 업로드\"를 누른다."
say "사용자 파라미터 하나당 재계산이 9번 이상이라 Fusion 화면이 한동안 멈춘다. 메시지 창이 뜰 때까지 기다린다."
note "\"업로드했습니다: <ID>\"가 뜨면 성공이다. \"업로드 실패\" 창이면 그 문장은 애드인이 $ADDIN_ERROR 에도 남긴다."
UPLOAD_ID=""
UPLOAD_ERROR=""
while [[ -z "$UPLOAD_ID" ]]; do
  pause "메시지 창이 뜨면 Enter"
  # shellcheck disable=SC2012  # ls는 위저드가 만드는 폴더의 파일 이름(공백·줄바꿈 없음)만 다룬다
  added=$(comm -13 <(printf '%s\n' "$before" | sort) <(ls data/uploads | sort) | grep '\.json$' | tail -n1 || true)
  if [[ -n "$added" ]]; then
    UPLOAD_ID=${added%.json}
    break
  fi
  warn "data/uploads/ 에 새 업로드가 없다."
  failed=$(addin_error "$MARK" "업로드 실패")
  if [[ -n "$failed" ]]; then
    warn "애드인이 업로드 실패를 남겼다: $failed"
    UPLOAD_ERROR="$failed"
    if confirm "고친 뒤 다시 누를까? (아니오면 실패로 적고 넘어간다)"; then
      touch "$MARK"
      continue
    fi
    SKIPPED+=("녹화(업로드 실패)")
    break
  fi
  if confirm "업로드는 성공했나? (메시지 창에 ID가 있으면 예)"; then
    ask UPLOAD_ID "메시지 창의 업로드 ID(32자리):"
    if ! curl -sf -m 10 -o /dev/null "$SERVER/uploads/$UPLOAD_ID"; then
      warn "서버에 그 ID가 없다. 다시 확인한다."
      UPLOAD_ID=""
    fi
  elif ! confirm "다시 기다릴까? (아니오면 실패로 적고 넘어간다)"; then
    ask UPLOAD_ERROR "업로드 실패 창의 문장(첫 줄과 마지막 줄이면 충분):"
    SKIPPED+=("녹화(업로드 실패)")
    break
  fi
done
[[ -n "$UPLOAD_ID" ]] && say "${GREEN}✓${RESET} 업로드를 받았다: $UPLOAD_ID"
rm -f "$MARK"
pause "Enter"

stage "녹화와 확인"
SUMMARY="$REC_DIR/$REC_NAME-summary.txt"
# 같은 이름의 예전 요점을 이번 결과로 읽지 않게, 이번에 만든 요점인지 적어 둔다
SUMMARY_FRESH=""
if [[ -n "$UPLOAD_ID" ]]; then
  body=$(mktemp)
  resp=$(mktemp)
  printf '{"name": "%s"}' "$REC_NAME" > "$body"
  code=$(curl -s -m 60 -o "$resp" -w '%{http_code}' -X POST -H "Content-Type: application/json" \
    --data-binary @"$body" "$SERVER/uploads/$UPLOAD_ID/recording" || true)
  if [[ "$code" == "201" && -f "$REC_DIR/$REC_NAME.json" ]]; then
    say "${GREEN}✓${RESET} 녹화본: $REC_DIR/$REC_NAME.json"
    status=0
    PYTHONUTF8=1 .venv/Scripts/python -m scripts.recording_summary "$REC_DIR/$REC_NAME.json" > "$SUMMARY" 2>&1 || status=$?
    SUMMARY_FRESH="예"
    (( status == 0 )) || warn "요점을 만들다 실패했다(종료 코드 $status). 아래 출력이 그 오류다."
    say ""
    while IFS= read -r line; do note "$line"; done < "$SUMMARY"
  elif [[ "$code" == "201" ]]; then
    warn "서버는 녹화했다는데 $REC_DIR/$REC_NAME.json 이 없다. 서버가 다른 폴더에 저장한다."
    SKIPPED+=("녹화본 위치(서버가 다른 폴더에 저장)")
  else
    warn "녹화 요청이 실패했다(HTTP ${code:-응답 없음}): $(head -c 300 "$resp")"
    SKIPPED+=("녹화 요청")
  fi
  rm -f "$body" "$resp"
else
  warn "업로드가 없어 녹화를 건너뛴다."
fi
pause "Enter"

stage "점검과 전달 항목"
NOTES="$REC_DIR/$REC_NAME-notes.md"
# 사람에게 Fusion 화면과 값을 비교시키지 않는다. 애드인이 업로드 뒤 스스로 잰 결과(_write_checks)를 읽는다.
CHECKS="data/addin-checks/${UPLOAD_ID:-none}.json"
RESTORED="점검 파일 없음"
PROXIES="점검 파일 없음"
RECOMPUTE="점검 파일 없음"
if [[ -f "$CHECKS" ]]; then
  # 파일이 깨졌거나 예전 형식이면 python이 실패한다. 그때도 위저드는 멈추지 않고 그 사실을 메모에 남긴다.
  read_status=0
  # 종료 코드: 0 그대로, 3 업로드 뒤 다시 되돌림(scripts/addin_checks.py RESTORED_AGAIN), 그 밖은 읽지 못함
  lines=$(PYTHONUTF8=1 .venv/Scripts/python -m scripts.addin_checks "$CHECKS" 2>&1) || read_status=$?
  if (( read_status == 0 || read_status == 3 )); then
    { read -r RESTORED; read -r PROXIES; read -r RECOMPUTE; } <<< "$lines"
  else
    RESTORED="점검 파일을 읽지 못함: $(tail -n1 <<< "$lines")"
    PROXIES="$RESTORED"
    RECOMPUTE="$RESTORED"
  fi
  say "애드인 점검(${CHECKS}):"
  note "  파라미터: $RESTORED"
  note "  어셈블리 좌표: $PROXIES"
  note "  재계산 실패 샘플(오류 피처): $RECOMPUTE"
  if (( read_status == 3 )); then
    warn "업로드가 끝난 뒤에도 달라진 파라미터가 있어 애드인이 되돌렸다. 모델은 원래대로다. 어댑터 결함이니 Claude에게 알린다."
  fi
elif [[ -n "$UPLOAD_ID" ]]; then
  warn "애드인 점검 파일($CHECKS)이 없다. 애드인을 중지·다시 실행하지 않아 예전 코드로 업로드했을 수 있다."
fi
if [[ -n "$SUMMARY_FRESH" ]] && grep -q "애드인이 쓴 꼴의 수식" "$SUMMARY"; then
  warn "요점에 애드인이 쓴 꼴의 수식이 있다. 앞 업로드가 끊겨 남긴 값이면 저장해 둔 판으로 다시 열고 다시 업로드한다."
fi
note "아래는 사람만 아는 정보다. 모르면 Enter로 넘어간다."
ask PARTS "부품마다 무엇인지(예: 상판=Top, 다리=Leg1~4):"
ask PARAM_MEANING "사용자 파라미터마다 뜻·축(W·D·H)·판매 범위(예: W=좌판 폭, W, 300~500):"
ask FRONT "정면 방향(예: -Y 쪽이 정면):"
ask OCCURRENCES "같은 컴포넌트를 여러 번 넣은 부품(좌·우 측판 등)이 따로 부품이 되는 것이 맞나? 없으면 Enter:"
ask FUSION_VERSION "Fusion 버전(도움말 → Fusion 정보, 모르면 Enter):"
ask ODDITIES "그 밖에 이상했던 점(없으면 Enter):"
{
  printf '# %s 녹화 메모 (%s)\n\n' "$REC_NAME" "$(date '+%Y-%m-%d %H:%M')"
  # shellcheck disable=SC2016  # 작은따옴표 안의 $·`는 일부러 펼치지 않는다(메모의 마크다운 코드, node 코드, 정규식)
  printf -- '- 커밋: `%s`\n' "$(git log -1 --format='%h %s')"
  printf -- '- 업로드 점검: %s\n' "$DRY_RESULT"
  printf -- '- 업로드 ID: %s\n' "${UPLOAD_ID:-없음}"
  [[ -n "$UPLOAD_ERROR" ]] && printf -- '- 업로드 실패: %s\n' "$UPLOAD_ERROR"
  # shellcheck disable=SC2016  # 작은따옴표 안의 $·`는 일부러 펼치지 않는다(메모의 마크다운 코드, node 코드, 정규식)
  printf -- '- 녹화본: `%s`, 요점: `%s`\n' "$REC_DIR/$REC_NAME.json" "$SUMMARY"
  printf -- '- 애드인 점검, 파라미터: %s\n' "$RESTORED"
  printf -- '- 애드인 점검, 어셈블리 좌표: %s\n' "$PROXIES"
  printf -- '- 애드인 점검, 재계산 실패 샘플: %s\n' "$RECOMPUTE"
  printf -- '- 부품 설명: %s\n' "${PARTS:-없음}"
  printf -- '- 파라미터 뜻: %s\n' "${PARAM_MEANING:-없음}"
  printf -- '- 정면: %s\n' "${FRONT:-없음}"
  printf -- '- 같은 컴포넌트 여러 번: %s\n' "${OCCURRENCES:-해당 없음}"
  printf -- '- Fusion 버전: %s\n' "${FUSION_VERSION:-모름}"
  printf -- '- 이상했던 점: %s\n' "${ODDITIES:-없음}"
} > "$NOTES"
say "${GREEN}✓${RESET} 메모를 $NOTES 에 썼다."
note "녹화본 백업은 저장소 밖(개인 드라이브 등)에 둔다. 정면·측면 화면 캡처를 $REC_DIR/ 에 두면 도움이 된다(선택)."
note "티켓 26은 공개 저장소에 있다. Claude는 판정 결과만 옮기고, 부품 이름·파라미터 뜻 같은 상품 정보는 이 메모에만 둔다."
say "Claude에게 \"녹화 끝, $NOTES\"라고 알린다."
pause "Enter"

finish
}

run_wizard "$@"; exit
